const error = $input.first().json;
const workflowName = error.workflow?.name || 'Unknown';
const workflowId = error.workflow?.id || '';
const executionId = error.execution?.id || '';
const errorMessage = error.execution?.error?.message || 'No error message';
const errorNode = error.execution?.error?.node?.name || 'Unknown node';
const errorNodeType = error.execution?.error?.node?.type || '';
const errorNodeId = error.execution?.error?.node?.id || '';
const errorStack = (error.execution?.error?.stack || '').substring(0, 800);
const errorDescription = error.execution?.error?.description || '';
const errorContext = JSON.stringify(error.execution?.error?.context || {}).substring(0, 300);
const httpCode = error.execution?.error?.httpCode || '';

const runData = error.execution?.data?.resultData?.runData || {};
let silentErrors = [];
let executedNodes = [];
let failedNodes = [];

for (const [nodeName, runs] of Object.entries(runData)) {
  executedNodes.push(nodeName);
  for (const run of runs) {
    if (run.error) {
      failedNodes.push({
        node: nodeName,
        message: (run.error.message || '').substring(0, 200),
        description: (run.error.description || '').substring(0, 200),
        httpCode: run.error.httpCode || ''
      });
    }
    const mainData = run.data?.main || [[]];
    const totalItems = mainData.reduce((sum, branch) => sum + (branch?.length || 0), 0);
    if (totalItems === 0 && !run.error) {
      silentErrors.push(nodeName + ': empty output');
    }
  }
}

const nodeErrorsText = failedNodes.map(e =>
  '- ' + e.node + ': ' + e.message +
  (e.httpCode ? ' (HTTP ' + e.httpCode + ')' : '') +
  (e.description ? ' | ' + e.description : '')
).join('\n');

const silentText = silentErrors.join('\n');

const prompt = 'You are an n8n expert. A workflow failed. Diagnose in detail.\n\n' +
  'MAIN ERROR:\n' +
  '- Workflow: ' + workflowName + ' (ID: ' + workflowId + ')\n' +
  '- Execution: ' + executionId + '\n' +
  '- Node: ' + errorNode + ' (type: ' + errorNodeType + ')\n' +
  '- Error: ' + errorMessage + '\n' +
  '- Description: ' + errorDescription + '\n' +
  '- HTTP Code: ' + httpCode + '\n' +
  '- Stack: ' + errorStack.substring(0, 400) + '\n' +
  '- Context: ' + errorContext + '\n\n' +
  'FAILED NODES (' + failedNodes.length + '):\n' +
  (nodeErrorsText || 'Only the main error') + '\n\n' +
  'NODES WITH EMPTY OUTPUT:\n' +
  (silentText || 'None') + '\n\n' +
  'EXECUTED NODES: ' + executedNodes.join(', ') + '\n\n' +
  'Respond ONLY JSON: {"diagnosis": "...", "root_cause": "...", "severity": "critical/high/medium/low", "suggested_action": "concrete action for the admin", "secondary_errors": "... or null"}';

return [{ json: {
  prompt,
  workflowName, workflowId, executionId,
  errorMessage, errorNode, errorNodeType, errorNodeId,
  errorDescription, httpCode,
  failedNodesCount: failedNodes.length,
  silentErrorsCount: silentErrors.length,
  executedNodesCount: executedNodes.length,
  nodeErrorsDetail: nodeErrorsText,
  originalError: error
} }];

const prev = $('Prepare Error Context').first().json;
const raw = ($input.first().json?.choices?.[0]?.message?.content || $input.first().json.stdout || '').trim();

let diagnosis;
try {
  let cleaned = raw;
  if (cleaned.startsWith('```')) {
    cleaned = cleaned.replace(/^```json?\n?/, '').replace(/\n?```$/, '').trim();
  }
  const match = cleaned.match(/\{[\s\S]*\}/);
  if (match) diagnosis = JSON.parse(match[0]);
} catch(e) {}

if (!diagnosis) {
  diagnosis = {
    diagnosis: 'AI could not analyze the error automatically',
    root_cause: prev.errorMessage,
    severity: 'high',
    suggested_action: 'Manually review node ' + prev.errorNode + ' in ' + prev.workflowName,
    secondary_errors: null
  };
}

if (!diagnosis.suggested_action) {
  diagnosis.suggested_action = diagnosis.recommendation || 'Review manually';
}

return [{ json: { ...prev, ...diagnosis } }];
